Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Quanto de cada C.Standard saiu?",
    "subtitle": "% do plano do mês · traço = ritmo esperado · vermelho = atrás do ritmo · clique na linha para filtrar",
    "anchor": "start",
    "font": "Segoe UI",
    "fontSize": 13,
    "fontWeight": 600,
    "color": "#3C3C3B",
    "subtitleFont": "Segoe UI",
    "subtitleFontSize": 10,
    "subtitleColor": "#8A8A88",
    "offset": 10
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "datum[''HP Plano do Mês''] > 0"
    },
    {
      "calculate": "datum[''HP % do Plano''] < datum[''HP % Ritmo Esperado''] ? ''atrás'' : ''em dia''",
      "as": "situacao"
    },
    {
      "calculate": "replace(format(datum[''HP % do Plano''], ''.1%''), ''.'', '','')",
      "as": "pct1"
    },
    {
      "calculate": "format(datum[''HP % do Plano''], ''.0%'')",
      "as": "pct0"
    },
    {
      "calculate": "replace(format(datum[''HP % Ritmo Esperado''], ''.1%''), ''.'', '','')",
      "as": "ritmo1"
    },
    {
      "calculate": "replace(format(datum[''HP Plano do Mês''], '',.0f''), regexp('','', ''g''), ''.'')",
      "as": "plano1"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "HP Plano do Mês",
          "as": "pmax"
        }
      ]
    },
    {
      "calculate": "datum.pmax - datum[''HP Plano do Mês'']",
      "as": "chave"
    },
    {
      "calculate": "datum[''C_Standard''] + ''   '' + replace(format(datum[''HP Plano do Mês''] / 1000, ''.1f''), ''.'', '','') + ''k''",
      "as": "rotulo"
    }
  ],
  "width": "container",
  "height": {
    "step": 24
  },
  "encoding": {
    "y": {
      "field": "rotulo",
      "type": "nominal",
      "sort": {
        "field": "chave",
        "op": "min",
        "order": "ascending"
      },
      "title": null,
      "axis": {
        "labelFont": "Segoe UI",
        "labelFontSize": 11,
        "labelColor": "#3C3C3B",
        "domain": false,
        "ticks": false,
        "labelPadding": 8,
        "labelLimit": 220
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadius": 2,
        "height": 11,
        "color": "#EDEDED"
      },
      "encoding": {
        "x": {
          "datum": 1,
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ]
          },
          "axis": null
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "cornerRadius": 2,
        "height": 11
      },
      "encoding": {
        "x": {
          "field": "HP % do Plano",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "clamp": true
          },
          "axis": null
        },
        "color": {
          "field": "situacao",
          "type": "nominal",
          "scale": {
            "domain": [
              "atrás",
              "em dia"
            ],
            "range": [
              "#E2000F",
              "#3C3C3B"
            ]
          },
          "legend": null
        },
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#3C3C3B",
        "thickness": 2,
        "size": 17
      },
      "encoding": {
        "x": {
          "field": "HP % Ritmo Esperado",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 6,
        "font": "Segoe UI",
        "fontSize": 11,
        "fontWeight": "bold"
      },
      "encoding": {
        "x": {
          "datum": 1,
          "type": "quantitative"
        },
        "text": {
          "field": "pct1"
        },
        "color": {
          "field": "situacao",
          "type": "nominal",
          "scale": {
            "domain": [
              "atrás",
              "em dia"
            ],
            "range": [
              "#E2000F",
              "#3C3C3B"
            ]
          },
          "legend": null
        }
      }
    },
    {
      "params": [
        {
          "name": "__select__",
          "select": {
            "type": "point"
          }
        },
        {
          "name": "passa",
          "select": {
            "type": "point",
            "on": "pointerover",
            "clear": "pointerout"
          }
        }
      ],
      "mark": {
        "type": "rect",
        "cursor": "pointer",
        "cornerRadius": 4
      },
      "encoding": {
        "x": {
          "value": -150
        },
        "x2": {
          "value": {
            "expr": "width + 46"
          }
        },
        "fill": {
          "condition": [
            {
              "param": "passa",
              "empty": false,
              "value": "rgba(60,60,59,0.08)"
            },
            {
              "test": "datum.__selected__ == ''on''",
              "value": "rgba(60,60,59,0.05)"
            }
          ],
          "value": "transparent"
        },
        "tooltip": [
          {
            "field": "C_Standard",
            "title": "C.Standard"
          },
          {
            "field": "plano1",
            "title": "Plano (m)"
          },
          {
            "field": "pct1",
            "title": "% do plano"
          },
          {
            "field": "ritmo1",
            "title": "Ritmo esperado"
          }
        ]
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "padding": {
      "left": 6,
      "right": 6,
      "top": 4,
      "bottom": 4
    }
  }
}'
